<?php
namespace App\Notifications;
use App\Models\Election; use App\Traits\HasOrganizationTheme; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class VotingNowOpenNotification extends Notification implements ShouldQueue
{ use Queueable, HasOrganizationTheme; protected $election;
 public function __construct(Election $election){$this->election=$election;if(config('queue.default') !== 'sync'){$this->onConnection('redis');$this->onQueue('emails');}} public function via(object $notifiable):array{return ['mail','database'];}
 public function toMail(object $notifiable):MailMessage{$t=$this->getOrganizationTheme($notifiable,$this->election->organization);return (new MailMessage)->subject('Voting is now open: '.$this->election->title)->view(['html'=>'emails.election','text'=>'emails.election-text'],['organizationName'=>$t['organization_name'],'organizationLogo'=>$t['logo_url'],'primaryColor'=>$t['primary_color'],'recipientName'=>$notifiable->first_name,'title'=>'Voting is now open','preheader'=>'Cast your vote before the election closes.','intro'=>'The voting period has started. Review the candidates, make your selections, and submit your vote before the deadline.','highlight'=>$this->election->title,'details'=>['Voting closes'=>$this->election->end_date->format('F j, Y, g:i A'),'Voting rule'=>'One vote per student'],'body'=>'Your vote is confidential. Make sure you have reviewed all positions before submitting because votes cannot be changed afterward.','actionLabel'=>'Vote now','actionUrl'=>url('/elections')]);}
 public function toArray(object $notifiable):array{return ['type'=>'voting_now_open','election_id'=>$this->election->id,'organization_id'=>$this->election->organization_id,'title'=>'Voting Now Open','message'=>$this->election->title,'icon'=>'ph-check-square','color'=>'green','url'=>url('/elections'),'end_date'=>$this->election->end_date->format('M j, Y g:i A')];}
}
